ls_err_t wifi_mfg_exec(char * params, int32_t params_len)
{
    mrpc_wifi_mfg_exec_req_t *req;
    mrpc_wifi_mfg_exec_resp_t resp;

    req = rtos_malloc(sizeof(mrpc_wifi_mfg_exec_req_t) + params_len);
    if (req == NULL)
        return  LS_FAIL;
    req->hdr.len = sizeof(mrpc_wifi_mfg_exec_req_t) + params_len;
    if (req->hdr.len > IPC_MSG_BUFFER_SIZE)
        return LS_FAIL;

    req->hdr.id = MRPC_MSG_ID_WIFI_MFG_EXEC;
    memcpy(req->data_buffer, params, params_len);
    req->params_len = params_len;
    if (mrpc_msg_send(req, req->hdr.len, &resp))
        return LS_FAIL;
    rtos_free(req);

    return (ls_err_t)resp.hdr.status;
}

